using RSSG.Core;
namespace RSSG.Host;
public interface IStarSystemHost { bool IsAuthoritativeServer {get;} void RegisterGenerateSystemMenuAction(Func<GenerationSettings,GeneratedStarSystem> action); void RegisterNewWorldGenerationHook(Func<GenerationSettings,GeneratedStarSystem> action); void PublishSystemToClients(GeneratedStarSystem system); }
public sealed class StarSystemService(StarSystemGenerator generator,IStarSystemHost host) { public GeneratedStarSystem GenerateFromMenu(GenerationSettings s)=>Generate(s); public GeneratedStarSystem GenerateForNewWorld(GenerationSettings s)=>Generate(s); public void RegisterBothModes(){host.RegisterGenerateSystemMenuAction(GenerateFromMenu);host.RegisterNewWorldGenerationHook(GenerateForNewWorld);} GeneratedStarSystem Generate(GenerationSettings s){if(!host.IsAuthoritativeServer)throw new InvalidOperationException("Only authoritative host may generate.");var system=generator.Generate(s);host.PublishSystemToClients(system);return system;} }